/**
 * Versioned artifact contracts shared by Node (runtime validation), the browser (Zod) and Python
 * (JSON Schema generated by scripts/generate-schemas.ts into analytics/schemas/).
 */
import { z } from 'zod';
import { CHANGE_TYPES, CONTENT_CHANGE_NATURES, EPISTEMIC_STATUSES, FILE_CLASSIFICATIONS, FINDING_CLASSIFICATIONS, FINDING_LEVELS, REVIEW_STATUSES } from '../domain/status.ts';
import { EDGE_TYPES, NODE_TYPES } from '../domain/graph.ts';

const sha = z.string().regex(/^[0-9a-f]{40}$/);
const sha256 = z.string().regex(/^[0-9a-f]{64}$/);
const epistemic = z.enum(EPISTEMIC_STATUSES);
const role = z.enum(['PRODUCTION_MAIN', 'REMODELING_MAIN']);
const finite = z.number().refine(Number.isFinite, 'finite number required');

export const SourceIdentitySchema = z.object({
  side: z.enum(['production', 'remodeling']),
  role,
  repository: z.string().regex(/^[A-Za-z0-9._-]+\/[A-Za-z0-9._-]+$/),
  requested_ref: z.string().min(1),
  commit_sha: sha,
  tree_sha: sha,
  committed_at: z.string().nullable(),
  headline: z.string().nullable(),
});

export const DeploymentSchema = z.object({
  status: z.enum(['DEPLOYMENT_VERIFIED', 'DEPLOYMENT_UNVERIFIED']),
  deployed_sha: sha.nullable(),
  evidence: z.array(z.object({
    kind: z.enum(['GITHUB_DEPLOYMENT_RECORD', 'LIVE_BUILD_IDENTIFIER']),
    accepted: z.boolean(),
    reference: z.string(),
    observed_sha: sha.nullable(),
    observed_at: z.string().nullable(),
    reason: z.string(),
  })),
  summary: z.string(),
}).refine((d) => (d.status === 'DEPLOYMENT_VERIFIED') === (d.deployed_sha !== null), 'deployed_sha must be set exactly when verified');

const sideValue = z.object({ present: z.boolean(), value: z.unknown().optional(), value_type: z.enum(['null', 'array', 'object', 'string', 'number', 'boolean', 'text']).optional() });
const sideProvenance = z.object({ repository: z.string(), commit_sha: sha, path: z.string(), blob_sha: sha.nullable(), line: z.number().int().positive().nullable().optional() });

export const FindingSchema = z.object({
  id: z.string().regex(/^CRD-[0-9A-F]{12}$/),
  level: z.enum(FINDING_LEVELS),
  classification: z.enum(FINDING_CLASSIFICATIONS),
  change_type: z.enum(CHANGE_TYPES),
  review_status: z.enum(REVIEW_STATUSES),
  priority: z.enum(['P1', 'P2', 'P3']),
  title: z.string(),
  file_path: z.string(),
  file_kind: z.enum(['json', 'markdown']),
  locator: z.string(),
  entity: z.object({ kind: z.enum(['country', 'record', 'document']), name: z.string() }).nullable(),
  field: z.string().nullable(),
  unit: z.string().nullable(),
  unit_source: z.literal('FIELD_NAME_CONVENTION').nullable(),
  production: sideValue,
  remodeling: sideValue,
  numeric_delta: z.object({ absolute: finite, relative: finite.nullable() }).nullable(),
  production_canon_status: z.string().nullable(),
  content_nature: z.enum(CONTENT_CHANGE_NATURES).nullable(),
  diff: z.object({ added_lines: z.number().int(), removed_lines: z.number().int(), excerpt: z.array(z.string()), truncated: z.boolean() }).nullable(),
  recommendation: z.string(),
  rule: z.string(),
  provenance: z.object({ production: sideProvenance.nullable(), remodeling: sideProvenance.nullable() }),
});

export const FileRecordSchema = z.object({
  path: z.string(),
  kind: z.enum(['json', 'markdown']),
  classification: z.enum(FILE_CLASSIFICATIONS),
  production_blob_sha: sha.nullable(),
  remodeling_blob_sha: sha.nullable(),
  production_bytes: z.number().int().nullable(),
  remodeling_bytes: z.number().int().nullable(),
  content_nature: z.enum(CONTENT_CHANGE_NATURES).nullable(),
  finding_count: z.number().int().nonnegative(),
  title: z.string().nullable(),
  analysis: z.enum(['COMPLETE', 'SKIPPED_OVERSIZE', 'NOT_REQUIRED', 'INVALID_SOURCE']),
});

const counts = z.record(z.string(), z.number().int().nonnegative());
export const AuditSchema = z.object({
  schema_version: z.literal('reltroner-statistics-audit.v2'),
  rules_version: z.string(),
  scope: z.object({ scope_id: z.string(), rules_version: z.string(), include: z.array(z.string()), exclude: z.array(z.string()), max_blob_bytes: z.number().int() }),
  sources: z.object({ production: SourceIdentitySchema, remodeling: SourceIdentitySchema }),
  deployment: DeploymentSchema,
  summary: z.object({
    total_compared_paths: z.number().int(), identical: z.number().int(), changed: z.number().int(), production_only: z.number().int(), draft_only: z.number().int(),
    changed_by_nature: counts, findings_total: z.number().int(), json_field_findings: z.number().int(),
    findings_by_level: counts, findings_by_classification: counts, findings_by_review_status: counts, findings_by_priority: counts,
  }),
  files: z.array(FileRecordSchema),
  findings: z.array(FindingSchema),
  semantic_digest: sha256,
  generated_at: z.string(),
}).refine((a) => a.summary.total_compared_paths === a.files.length && a.summary.findings_total === a.findings.length, 'summary must match records');

const period = z.object({
  calendar: z.literal('BAC'),
  year_bac: z.number().int().min(0).max(10000),
  label: z.string(),
  interval: z.object({ start_bac: z.number().int().min(0), end_bac: z.number().int().min(0) }).optional(),
});
const obsSource = z.object({ role, repository: z.string(), commit_sha: sha, path: z.string(), blob_sha: sha, pointer: z.string().nullable(), line: z.number().int().positive().nullable() });

export const ObservationSchema = z.object({
  id: z.string().regex(/^OBS-[0-9A-F]{12}$/),
  entity_id: z.string(),
  entity_name: z.string(),
  entity_kind: z.enum(['country', 'planet', 'aggregate_residual']),
  cohort: z.enum(['PROFILED_14', 'DEVELOPMENT_5', 'PLANET', 'DEFERRED_18_AGGREGATE']),
  indicator_id: z.string(),
  value: finite.nullable(),
  value_state: z.enum(['ASSIGNED', 'NULL', 'MISSING']),
  unit: z.string(),
  period,
  status: epistemic,
  source: obsSource,
  model_version: z.string().nullable(),
  source_status_label: z.string().nullable(),
  evidence: z.object({ rule_id: z.string(), quote: z.string(), note: z.string().nullable() }).nullable(),
}).refine((o) => (o.value === null) === (o.value_state !== 'ASSIGNED'), 'null value exactly when not assigned')
  .refine((o) => o.value !== null || o.status === 'INSUFFICIENT_DATA' || o.status === 'PROPOSED', 'unassigned values must be INSUFFICIENT_DATA');

export const StatisticsDatasetSchema = z.object({
  schema_version: z.literal('reltroner-statistics-observations.v1'),
  model_version: z.string().nullable(),
  dataset_path: z.string(),
  production: z.object({ commit_sha: sha, blob_sha: sha }).nullable(),
  remodeling: z.object({ commit_sha: sha, blob_sha: sha }).nullable(),
  entities: z.array(z.object({
    id: z.string(), name: z.string(), kind: z.enum(['country', 'planet', 'aggregate_residual']),
    cohort: z.enum(['PROFILED_14', 'DEVELOPMENT_5', 'PLANET', 'DEFERRED_18_AGGREGATE']),
    source_document: z.string().nullable(), specialization: z.string().nullable(), fx_code: z.string().nullable(),
    foundation_bac: z.number().int().nullable(), represents_states: z.number().int().nonnegative(), canon_status: z.string().nullable(),
  })),
  observations: z.array(ObservationSchema),
  proposals: z.array(ObservationSchema),
  timeline: z.array(z.object({
    id: z.string(), label: z.string(), start_bac: z.number().int(), end_bac: z.number().int(), kind: z.enum(['FOUNDATION', 'EVENT']),
    entity_id: z.string().nullable(), status: epistemic, source: obsSource, note: z.string().nullable(),
  })),
  ranges: z.array(z.object({
    id: z.string(), entity_id: z.string(), indicator_id: z.string(), low: finite, high: finite, unit: z.string(), timing: z.string(),
    status: epistemic, quote: z.string(), source: obsSource,
  })),
  migration: z.object({
    flows: z.array(z.object({ origin: z.string(), destination: z.string(), population_billion: finite, source_sdi_unchanged: finite.nullable() })),
    total_billion: finite.nullable(), status: epistemic, source: obsSource.nullable(),
  }),
  source_issues: z.array(z.object({ code: z.string(), severity: z.string(), description: z.string(), source: obsSource })),
  evidence_checks: z.array(z.object({ rule_id: z.string(), path: z.string(), status: z.enum(['VERIFIED', 'NOT_FOUND', 'SOURCE_MISSING']), line: z.number().int().nullable() })),
  unknowns: z.array(z.string()),
});

export const QaCheckSchema = z.object({
  id: z.string(), title: z.string(), formula: z.string(), scope: role, result: z.enum(['PASS', 'FAIL', 'NOT_EVALUABLE']),
  observed: finite.nullable(), expected: finite.nullable(), tolerance: z.number(), detail: z.string(),
  failures: z.array(z.object({ subject: z.string(), observed: finite, expected: finite })),
  pointers: z.array(z.string()),
  validates: z.object({ target: z.string(), inputs: z.array(z.string()) }).nullable(),
});
export const QaReportSchema = z.object({
  schema_version: z.literal('reltroner-statistics-qa.v1'),
  production: z.array(QaCheckSchema),
  remodeling: z.array(QaCheckSchema),
});

export const GraphSchema = z.object({
  schema_version: z.literal('reltroner-statistics-graph.v1'),
  nodes: z.array(z.object({
    id: z.string(), type: z.enum(NODE_TYPES), label: z.string(), side: z.enum(['production', 'remodeling', 'both']), group: z.string().nullable(),
    attrs: z.record(z.string(), z.union([z.string(), z.number(), z.boolean(), z.null()])),
  })),
  edges: z.array(z.object({
    id: z.string(), type: z.enum(EDGE_TYPES), source: z.string(), target: z.string(), side: z.enum(['production', 'remodeling', 'both']),
    status: z.enum(['DECLARED', 'VERIFIED', 'CANDIDATE']), evidence: z.string(),
  })),
  summary: z.object({ nodes_by_type: counts, edges_by_type: counts, edges_by_status: counts, edges_by_side: counts }),
}).refine((g) => {
  const ids = new Set(g.nodes.map((n) => n.id));
  return g.edges.every((e) => ids.has(e.source) && ids.has(e.target));
}, 'every edge must reference existing nodes');

const statN = finite.nullable();
export const AnalyticsSchema = z.object({
  schema_version: z.literal('reltroner-statistics-analytics.v1'),
  status: z.literal('MODEL_ESTIMATE'),
  engine: z.record(z.string(), z.string()),
  input: z.object({ observations_sha256: sha256, model_version: z.string().nullable(), production_commit: sha.nullable() }),
  descriptive: z.array(z.object({
    indicator_id: z.string(), cohort: z.enum(['PROFILED_14', 'ALL_19']), status: z.enum(['COMPUTED', 'INSUFFICIENT_DATA']),
    n: z.number().int(), n_missing: z.number().int(), mean: statN, median: statN, std: statN, min: statN, max: statN,
    q1: statN, q3: statN, iqr: statN, mad: statN, whisker_low: statN, whisker_high: statN,
    outliers: z.array(z.object({ entity_id: z.string(), value: finite })), reason: z.string().nullable(),
  })),
  correlation: z.object({
    status: z.enum(['COMPUTED', 'INSUFFICIENT_DATA']), cohort: z.string(), features: z.array(z.string()), n: z.number().int(),
    pearson: z.array(z.array(statN)), spearman: z.array(z.array(statN)), pairwise_n: z.array(z.array(z.number().int())), min_pairwise_n: z.number().int(), reason: z.string().nullable(),
  }),
  clustering: z.object({
    status: z.enum(['COMPUTED', 'INSUFFICIENT_DATA']), cohort: z.string(), n: z.number().int(), reason: z.string().nullable(),
    features: z.array(z.object({ indicator_id: z.string(), transform: z.enum(['none', 'log10']) })),
    scaling: z.string(), excluded_entities: z.array(z.object({ entity_id: z.string(), reason: z.string() })),
    sufficiency: z.object({ min_n: z.number().int(), rule: z.string() }),
    pca: z.object({ explained_variance_ratio: z.array(finite), loadings: z.array(z.array(finite)), coordinates: z.array(z.object({ entity_id: z.string(), pc1: finite, pc2: finite })) }).nullable(),
    kmeans: z.object({
      random_state: z.number().int(), n_init: z.number().int(), selection_rule: z.string(), recommended_k: z.number().int().nullable(),
      runs: z.array(z.object({ k: z.number().int(), inertia: finite, silhouette: finite.nullable(), sizes: z.array(z.number().int()), labels: z.array(z.object({ entity_id: z.string(), cluster: z.number().int() })), centroids_z: z.array(z.array(finite)) })),
    }).nullable(),
    dbscan: z.object({
      eps: finite, min_samples: z.number().int(), eps_rule: z.string(), k_distances: z.array(finite),
      labels: z.array(z.object({ entity_id: z.string(), cluster: z.number().int() })), n_clusters: z.number().int(), n_noise: z.number().int(),
    }).nullable(),
  }),
  outliers: z.array(z.object({
    indicator_id: z.string(), cohort: z.string(), status: z.enum(['COMPUTED', 'INSUFFICIENT_DATA']), method: z.string(), threshold: finite,
    n: z.number().int(), median: statN, mad: statN, flagged: z.array(z.object({ entity_id: z.string(), value: finite, robust_z: finite })), reason: z.string().nullable(),
  })),
  history: z.object({
    rule: z.string(),
    series: z.array(z.object({
      entity_id: z.string(), indicator_id: z.string(), n: z.number().int(), years_bac: z.array(z.number().int()), statuses: z.array(z.string()),
      max_consecutive_annual: z.number().int(),
      volatility: z.object({ status: z.enum(['COMPUTED', 'INSUFFICIENT_DATA']), reason: z.string(), rolling_median: z.array(statN).nullable(), rolling_mad: z.array(statN).nullable() }),
      change_point: z.object({ status: z.enum(['COMPUTED', 'INSUFFICIENT_DATA']), reason: z.string() }),
    })),
  }),
  charts: z.array(z.object({ id: z.string(), title: z.string(), file: z.string().regex(/^charts\/[a-z0-9-]+\.svg$/), sha256, alt: z.string() })),
  digest: sha256,
});

export const ArtifactManifestSchema = z.object({
  schema_version: z.literal('reltroner-statistics-artifacts.v1'),
  mode: z.literal('SOURCE_PINNED'),
  generated_at: z.string(),
  rules_version: z.string(),
  semantic_digest: sha256,
  sources: z.object({ production: SourceIdentitySchema, remodeling: SourceIdentitySchema }),
  deployment: z.object({ status: z.enum(['DEPLOYMENT_VERIFIED', 'DEPLOYMENT_UNVERIFIED']), deployed_sha: sha.nullable() }),
  github: z.object({ authenticated: z.boolean(), requests: z.number().int(), cache_hits: z.number().int(), cache_misses: z.number().int() }),
  steps: z.array(z.object({ id: z.string(), status: z.enum(['COMPLETED', 'SKIPPED']), detail: z.string() })),
  files: z.array(z.object({ path: z.string(), bytes: z.number().int(), sha256 })),
});

export const JSON_SCHEMA_EXPORTS = Object.freeze({
  'audit.schema.json': AuditSchema,
  'observations.schema.json': StatisticsDatasetSchema,
  'qa.schema.json': QaReportSchema,
  'graph.schema.json': GraphSchema,
  'analytics.schema.json': AnalyticsSchema,
  'manifest.schema.json': ArtifactManifestSchema,
});
